    "seo_description": "A complete GoHighLevel Stripe integration guide: connect Stripe, run subscriptions, set up SaaS Mode rebilling, handle webhooks, and fix common payment issues.",
    "seo_keywords": "gohighlevel stripe integration, ghl stripe subscriptions, stripe webhooks ghl, gohighlevel payments, connect stripe to gohighlevel",
    "featured": false,
    "published": true,
    "published_at": "2026-06-15T09:40:00.000Z",
    "created_at": "2026-06-15T09:40:00.000Z",
    "updated_at": "2026-06-15T09:40:00.000Z"
